INSERT INTO `products` VALUES (980,'pl6rckitjio869yeis0sq9p0','ORIA DTF A3','mesin-dtf-printing-oria-a3','Optimalkan produksi apparel dengan Mesin DTF ORIA A3. Lebar cetak 33 cm, tinta CMYKW, dan sistem sirkulasi tinta putih otomatis untuk hasil transfer berkualitas.','<p class=\"story-lead\"><strong>ORIA DTF A3</strong> merupakan paket cetak sablon transfer digital yang ringkas untuk usaha distro, clothing line, dan sablon custom.</p>\n<p>Sirkulasi tinta putih otomatis menjaga kepekatan warna dasar agar desain penuh warna menempel rapi pada kaos terang maupun gelap.</p>','Oria','New','InStock',0,72000000,NULL,NULL,NULL,'ORIA DTF A3 | ORIA','Tingkatkan produksi apparel dengan Mesin DTF ORIA A3. Lebar cetak 33 cm, pilihan printhead XP600 hingga i3200, dan sistem sirkulasi tinta putih otomatis.',NULL,'ASM-ORIA-980','ASM-ORIA-980',4.60,10,'Oria DTF A3','2026-04-25 04:55:26.000000','2026-11-16 15:48:07.213000',NULL,NULL,1,'en','https://drive.google.com/file/d/1i5DYqtqEJDZE2y0MhxmLqNAppMua9CSf/view?usp=sharing',NULL,'<div><figure class=\"table\"><table class=\"ck-table-resized\"><colgroup><col style=\"width:50%;\"><col style=\"width:50%;\"></colgroup><tbody><tr style=\"height:36px;\"><td style=\"background-color:#d9d9d9;border-color:#ffffff;border-width:2px;font-size:13.3334px;\">Print Head</td><td style=\"background-color:#ffffff;border-color:#ffffff;border-width:2px;font-size:13.3334px;\">XP600 / 4720 / i3200 × 2 Print Heads</td></tr><tr style=\"height:36px;\"><td style=\"background-color:#d9d9d9;border-color:#ffffff;border-width:2px;font-size:13.3334px;\">Max. Print Width</td><td style=\"background-color:#ffffff;border-color:#ffffff;border-width:2px;font-size:13.3334px;\">33 cm</td></tr><tr style=\"height:36px;\"><td style=\"background-color:#d9d9d9;border-color:#ffffff;border-width:2px;font-size:13.3334px;\">Color Configuration</td><td style=\"background-color:#ffffff;border-color:#ffffff;border-width:2px;font-size:13.3334px;\">Multicolor</td></tr><tr style=\"height:36px;\"><td style=\"background-color:#d9d9d9;border-color:#ffffff;border-width:2px;font-size:13.3334px;\">Ink Color</td><td style=\"background-color:#ffffff;border-color:#ffffff;border-width:2px;font-size:13.3334px;\">CMYKW</td></tr><tr style=\"height:36px;\"><td style=\"background-color:#d9d9d9;border-color:#ffffff;border-width:2px;font-size:13.3334px;\">Ink Type</td><td style=\"background-color:#ffffff;border-color:#ffffff;border-width:2px;font-size:13.3334px;\">Pigment Ink</td></tr><tr style=\"height:36px;\"><td style=\"background-color:#d9d9d9;border-color:#ffffff;border-width:2px;font-size:13.3334px;\">Ink System</td><td style=\"background-color:#ffffff;border-color:#ffffff;border-width:2px;font-size:13.3334px;\">Automatic White Ink Circulation System</td></tr><tr style=\"height:36px;\"><td style=\"background-color:#d9d9d9;border-color:#ffffff;border-width:2px;font-size:13.3334px;\">Media Compatibility</td><td style=\"background-color:#ffffff;border-color:#ffffff;border-width:2px;font-size:13.3334px;\">All Fabric</td></tr><tr style=\"height:36px;\"><td style=\"background-color:#d9d9d9;border-color:#ffffff;border-width:2px;font-size:13.3334px;\">RIP Software</td><td style=\"background-color:#ffffff;border-color:#ffffff;border-width:2px;font-size:13.3334px;\">Maintop / PhotoPrint / Flexi (Optional)</td></tr><tr style=\"height:36px;\"><td style=\"background-color:#d9d9d9;border-color:#ffffff;border-width:2px;font-size:13.3334px;\">Dimensions (L × W × H)</td><td style=\"background-color:#ffffff;border-color:#ffffff;border-width:2px;font-size:13.3334px;\">145 × 72 × 66 cm + 130 × 65 × 101 cm</td></tr><tr style=\"height:36px;\"><td style=\"background-color:#d9d9d9;border-color:#ffffff;border-width:2px;font-size:13.3334px;\">Weight</td><td style=\"background-color:#ffffff;border-color:#ffffff;border-width:2px;font-size:13.3334px;\">151 kg</td></tr><tr style=\"height:36px;\"><td style=\"background-color:#d9d9d9;border-color:#ffffff;border-width:2px;font-size:13.3334px;